     1→import type { Database } from "bun:sqlite";
     2→import type { Server, ServerWebSocket } from "bun";
     3→import type { WsData, FogMask, Token } from "../types";
     4→import { getAdventure, getAdventureByPlayerLink, setActiveImage } from "../db/adventures";
     5→import { getImage } from "../db/images";
     6→import { repairImageDimensions } from "../routes";
     7→import { findOrCreateToken, createToken, getTokensByAdventure, updateTokenPosition, deleteToken } from "../db/tokens";
     8→import { createMask, applyStroke, applyStrokes } from "../fog/mask";
     9→import { serializeMask, saveFogMask, loadFogMask } from "../fog/serialize";
    10→import {
    11→  registerConnection,
    12→  unregisterConnection,
    13→  getConnection,
    14→  getConnectionsForAdventure,
    15→  getWsForToken,
    16→  getGmWsForAdventure,
    17→} from "./connections";
    18→import { parseMessage, serializeMessage } from "./messages";
    19→
    20→// ---- Fog mask in-memory cache ----
    21→
    22→const fogMaskCache = new Map<string, FogMask>(); // keyed by imageId
    23→const saveTimers = new Map<string, ReturnType<typeof setTimeout>>();
    24→
    25→async function getFogMaskForImage(db: Database, imageId: string, uploadsDir?: string): Promise<FogMask> {
    26→  if (fogMaskCache.has(imageId)) return fogMaskCache.get(imageId)!;
    27→  const loaded = await loadFogMask(db, imageId);
    28→  if (loaded) {
    29→    fogMaskCache.set(imageId, loaded);
    30→    return loaded;
    31→  }
    32→  let image = getImage(db, imageId);
    33→  if (!image) throw new Error(`Image ${imageId} not found`);
    34→  if ((image.width === 0 || image.height === 0) && uploadsDir) {
    35→    repairImageDimensions(db, imageId, uploadsDir);
    36→    image = getImage(db, imageId) ?? image;
    37→  }
    38→  const mask = createMask(image.width, image.height);
    39→  fogMaskCache.set(imageId, mask);
    40→  return mask;
    41→}
    42→
    43→function scheduleSave(db: Database, imageId: string): void {
    44→  const existing = saveTimers.get(imageId);
    45→  if (existing) clearTimeout(existing);
    46→  const timer = setTimeout(async () => {
    47→    saveTimers.delete(imageId);
    48→    const mask = fogMaskCache.get(imageId);
    49→    if (mask) await saveFogMask(db, imageId, mask);
    50→  }, 500);
    51→  saveTimers.set(imageId, timer);
    52→}
    53→
    54→export async function flushAllFogCaches(db: Database): Promise<void> {
    55→  for (const timer of saveTimers.values()) clearTimeout(timer);
    56→  saveTimers.clear();
    57→  for (const [imageId, mask] of fogMaskCache) {
    58→    await saveFogMask(db, imageId, mask);
    59→  }
    60→}
    61→
    62→async function maskToBase64(mask: FogMask): Promise<string> {
    63→  const buf = await serializeMask(mask);
    64→  return buf.toString("base64");
    65→}
    66→
    67→// ---- Roster helpers ----
    68→
    69→function buildRoster(
    70→  db: Database,
    71→  adventureId: string
    72→): Array<{ tokenId: string; name: string; color: string; online: boolean }> {
    73→  const tokens = getTokensByAdventure(db, adventureId);
    74→  const conns = getConnectionsForAdventure(adventureId);
    75→  const onlineTokenIds = new Set(conns.map((c) => c.tokenId).filter(Boolean));
    76→  return tokens
    77→    .filter((t) => t.player_link !== null)
    78→    .map((t) => ({
    79→      tokenId: t.id,
    80→      name: t.name,
    81→      color: t.color,
    82→      online: onlineTokenIds.has(t.id),
    83→    }));
    84→}
    85→
    86→function sendRosterToGm(db: Database, adventureId: string): void {
    87→  const gmWs = getGmWsForAdventure(adventureId);
    88→  if (!gmWs) return;
    89→  gmWs.send(
    90→    serializeMessage({ type: "player:roster", players: buildRoster(db, adventureId) })
    91→  );
    92→}
    93→
    94→// ---- WebSocket upgrade (called from fetch handler) ----
    95→
    96→export function handleWsUpgrade(
    97→  req: Request,
    98→  db: Database,
    99→  server: Server
   100→): Response | undefined {
   101→  const url = new URL(req.url);
   102→  const adventureId = url.searchParams.get("adventureId");
   103→  const role = url.searchParams.get("role") as "gm" | "player" | null;
   104→  const password = url.searchParams.get("password");
   105→  const playerLink = url.searchParams.get("playerLink");
   106→  const playerName = url.searchParams.get("playerName");
   107→  const playerColor = url.searchParams.get("playerColor");
   108→
   109→  if (!adventureId || !role) {
   110→    return new Response("adventureId and role are required", { status: 400 });
   111→  }
   112→  if (role !== "gm" && role !== "player") {
   113→    return new Response("role must be gm or player", { status: 400 });
   114→  }
   115→
   116→  const adventure = getAdventure(db, adventureId);
   117→  if (!adventure) {
   118→    return new Response("Adventure not found", { status: 404 });
   119→  }
   120→
   121→  let tokenId: string | undefined;
   122→  let resolvedPlayerLink: string | undefined;
   123→  let tokenIsNew: boolean | undefined;
   124→
   125→  if (role === "gm") {
   126→    if (!password || password !== adventure.gm_password) {
   127→      return new Response("Invalid password", { status: 401 });
   128→    }
   129→  } else {
   130→    if (!playerLink) {
   131→      return new Response("playerLink is required for players", { status: 400 });
   132→    }
   133→    const linked = getAdventureByPlayerLink(db, playerLink);
   134→    if (!linked || linked.id !== adventureId) {
   135→      return new Response("Invalid player link", { status: 401 });
   136→    }
   137→    if (!playerName || !playerColor) {
   138→      return new Response("playerName and playerColor are required", { status: 400 });
   139→    }
   140→    // Identity key: adventure invite link + player name.
   141→    // Same bookmark URL (same name) → same token. Different name → different token.
   142→    const playerIdentity = `${playerLink}|${playerName}`;
   143→    const { token, isNew } = findOrCreateToken(db, {
   144→      adventureId,
