}

/* ── Floating panel (slide-out sheets) ── */
.floating-panel {
  position: fixed;
  z-index: 10;
  background: rgba(26, 26, 46, 0.85);
  backdrop-filter: blur(8px);
  -webkit-backdrop-filter: blur(8px);
