  const fogMaskBase64 = await maskToBase64(freshMask);
  const resetMsg = serializeMessage({ type: "fog:reset", imageId, fogMask: fogMaskBase64 });
  ws.send(resetMsg);
  ws.publish(topic, resetMsg);
  break;
}

case "ping": {
  ws.send(serializeMessage({ type: "pong" }));
  break;
}

