*, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }

body {
  font-family: system-ui, sans-serif;
  background: #0d0d1a;
  color: #e0e0e0;
  height: 100vh;
  overflow: hidden;
}

/* ── Home page ── */
body.home {
  display: flex;
  align-items: center;
  justify-content: center;
  overflow: auto;
}
.home-main { width: 100%; max-width: 480px; padding: 2rem; }
.home-main h1 {
  font-size: 2rem;
  margin-bottom: 1.5rem;
  text-align: center;
  letter-spacing: 0.04em;
  color: #fff;
}
.card {
  background: rgba(26, 26, 46, 0.6);
  backdrop-filter: blur(8px);
  -webkit-backdrop-filter: blur(8px);
  border: 1px solid rgba(42, 42, 74, 0.5);
  border-radius: 12px;
  padding: 1.5rem;
  margin-bottom: 1rem;
  box-shadow: 0 4px 24px rgba(0, 0, 0, 0.3);
}
@supports not (backdrop-filter: blur(8px)) {
  .card { background: #1a1a2e; }
}
.card h2 {
  margin-bottom: 1rem;
  font-size: 1.15rem;
  letter-spacing: 0.03em;
  color: #fff;
}
.card label { display: flex; flex-direction: column; gap: 4px; margin-bottom: 0.75rem; font-size: 0.85rem; color: #aaa; }
.card input[type=text],
.card input[type=password] {
  padding: 0 0.75rem;
  min-height: 44px;
  background: rgba(13, 13, 26, 0.8);
  border: 1px solid rgba(42, 42, 74, 0.6);
  border-radius: 8px;
  color: #e0e0e0;
  font-size: 1rem;
  outline: none;
  transition: border-color 200ms ease-out, box-shadow 200ms ease-out;
}
.card input[type=text]:focus,
.card input[type=password]:focus {
  border-color: #4a4aff;
  box-shadow: 0 0 0 2px rgba(74, 74, 255, 0.3);
}
.card input[type=color] {
  min-height: 44px;
  width: 100%;
  padding: 4px;
  background: rgba(13, 13, 26, 0.8);
  border: 1px solid rgba(42, 42, 74, 0.6);
  border-radius: 8px;
  cursor: pointer;
}
.card button {
  width: 100%;
  min-height: 44px;
  padding: 0 1rem;
  background: #4a4aff;
  color: #fff;
  border: none;
  border-radius: 8px;
  cursor: pointer;
  font-size: 1rem;
  font-weight: 600;
  transition: background-color 200ms ease-out, transform 200ms ease-out;
}
.card button:hover { background: #3333cc; }
.card button:active { transform: scale(0.98); }
.error {
  color: #e74c3c;
  margin-top: 0.5rem;
  font-size: 0.85rem;
  border-left: 2px solid #e74c3c;
  padding-left: 0.5rem;
}
.error:empty { display: none; }
@media (max-width: 400px) {
  .home-main { padding: 1rem; }
  .card { padding: 1rem; }
}

/* ── Canvas area (GM and Player) ── */
#canvas-area {
  position: fixed;
  inset: 0;
  display: flex;
  align-items: center;
  justify-content: center;
  background: #080810;
  overflow: hidden;
  touch-action: none;
}

/* ── Floating control base ── */
.floating-control {
  position: fixed;
  z-index: 10;
  background: rgba(26, 26, 46, 0.6);
  backdrop-filter: blur(8px);
  -webkit-backdrop-filter: blur(8px);
  border: 1px solid rgba(42, 42, 74, 0.5);
  border-radius: 8px;
  color: #e0e0e0;
  pointer-events: auto;
  transition: opacity 200ms ease-out, transform 200ms ease-out;
}

/* ── Floating panel (slide-out sheets) ── */
.floating-panel {
  position: fixed;
  z-index: 10;
  background: rgba(26, 26, 46, 0.85);
  backdrop-filter: blur(8px);
  -webkit-backdrop-filter: blur(8px);
  border: 1px solid rgba(42, 42, 74, 0.5);
  border-left: 1px solid rgba(42, 42, 74, 0.5);
  color: #e0e0e0;
  pointer-events: auto;
  transition: transform 200ms ease-out, opacity 200ms ease-out;
}

/* ── GM Topbar ── */
#topbar {
  top: 8px;
  left: 8px;
  right: 8px;
  height: 44px;
  display: flex;
  align-items: center;
  gap: 0.75rem;
  padding: 0 0.75rem;
}
#adventure-name {
  font-weight: 600;
  white-space: nowrap;
  flex: 1;
  min-width: 0;
  overflow: hidden;
  text-overflow: ellipsis;
}

/* ── Connection status dot ── */
.status-dot {
  width: 8px;
  height: 8px;
  border-radius: 50%;
  background: #555;
  flex-shrink: 0;
}
.status-dot.connected { background: #22c55e; }
.status-dot.disconnected { background: #e74c3c; }

/* ── Player presence avatar stack ── */
#player-presence {
  display: flex;
  align-items: center;
  flex-shrink: 0;
}
.presence-avatar {
  width: 32px;
  height: 32px;
  border-radius: 50%;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 0.75rem;
  font-weight: 700;
  color: #fff;
  cursor: pointer;
  border: 2px solid transparent;
  margin-left: -8px;
  position: relative;
  transition: transform 150ms ease-out;
  flex-shrink: 0;
  user-select: none;
}
.presence-avatar:first-child { margin-left: 0; }
.presence-avatar.online { box-shadow: 0 0 0 2px #22c55e; }
.presence-avatar.offline { opacity: 0.5; }
.presence-avatar:hover { transform: scale(1.15); z-index: 1; }
.presence-overflow { background: #444 !important; }

/* ── Presence popover ── */
.presence-popover {
  position: fixed;
  top: 60px;
  right: 8px;
  min-width: 240px;
  background: rgba(26, 26, 46, 0.95);
  backdrop-filter: blur(8px);
  -webkit-backdrop-filter: blur(8px);
  border: 1px solid rgba(42, 42, 74, 0.7);
  border-radius: 8px;
  z-index: 50;
  padding: 0.4rem 0;
  box-shadow: 0 4px 24px rgba(0, 0, 0, 0.5);
}
.popover-player {
  display: flex;
  align-items: center;
  gap: 0.5rem;
  padding: 0.4rem 0.75rem;
}
.popover-player-dot {
  width: 10px;
  height: 10px;
  border-radius: 50%;
  flex-shrink: 0;
}
.popover-player-name {
  flex: 1;
  font-size: 0.85rem;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}
.popover-player-status {
  font-size: 0.75rem;
  color: #888;
  flex-shrink: 0;
}
.popover-player-actions {
  display: flex;
  gap: 0.25rem;
  flex-shrink: 0;
}
.popover-btn {
  padding: 0.2rem 0.4rem;
  min-height: 28px;
  background: transparent;
  border: 1px solid #333;
  border-radius: 4px;
  color: #aaa;
  cursor: pointer;
  font-size: 0.75rem;
  white-space: nowrap;
}
.popover-btn:hover { background: #1a1a2e; color: #ccc; }
.popover-btn.danger:hover { background: #3a1a1a; color: #e74c3c; border-color: #e74c3c; }

/* ── Brush slider: left edge, vertically centered ── */
#brush-slider {
  left: 8px;
  top: 50%;
  transform: translateY(-50%);
  display: flex;
  flex-direction: column;
  align-items: center;
  padding: 0.5rem 0.5rem;
  gap: 0.4rem;
  width: 44px;
}
#brush-size {
  writing-mode: vertical-lr;
  direction: rtl;
  -webkit-appearance: slider-vertical;
  height: 150px;
  width: 24px;
  accent-color: #4a4aff;
  cursor: pointer;
  touch-action: auto;
}
#brush-size-label {
  font-size: 0.7rem;
  color: #aaa;
  text-align: center;
}

/* ── Mode toggle: bottom-left pill ── */
#mode-toggle {
  left: 8px;
  bottom: 8px;
  display: flex;
  flex-direction: row;
  padding: 4px;
  gap: 4px;
  border-radius: 12px;
}
#mode-toggle button {
  width: 68px;
  height: 44px;
  background: transparent;
  border: none;
  border-radius: 8px;
  color: #aaa;
  cursor: pointer;
  font-size: 0.85rem;
  transition: background 150ms ease-out, color 150ms ease-out;
  touch-action: auto;
}
#mode-toggle button.active { background: #4a4aff; color: #fff; }
#mode-toggle button:not(.active):hover { background: rgba(255, 255, 255, 0.05); color: #ccc; }

/* ── Map panel toggle: right edge icon button ── */
#map-panel-toggle {
  right: 8px;
  top: 50%;
  transform: translateY(-50%);
  width: 44px;
  height: 44px;
  display: flex;
  align-items: center;
  justify-content: center;
  cursor: pointer;
  padding: 0;
  background: rgba(26, 26, 46, 0.6);
}
#map-panel-toggle:hover { background: rgba(42, 42, 74, 0.8); }
#map-panel-toggle.active { background: rgba(74, 74, 255, 0.25); border-color: #4a4aff; }

/* ── Map panel: right-side slide-in sheet ── */
#map-panel {
  right: 0;
  top: 60px;
  bottom: 0;
  width: 200px;
  display: flex !important;
  flex-direction: column;
  border-radius: 8px 0 0 8px;
  transform: translateX(0);
  opacity: 1;
}
#map-panel[hidden] {
  transform: translateX(105%);
  opacity: 0;
  pointer-events: none;
}
#gallery {
  flex: 1;
  overflow-y: auto;
  padding: 0.5rem;
  display: flex;
  flex-direction: column;
  gap: 0.5rem;
}
.gallery-item {
  border: 2px solid transparent;
  border-radius: 4px;
  cursor: pointer;
  overflow: hidden;
  background: #0d0d1a;
  touch-action: auto;
}
.gallery-item:hover { border-color: #4a4aff88; }
.gallery-item.active { border-color: #4a4aff; }
.gallery-item img { width: 100%; height: 80px; object-fit: cover; display: block; }
.upload-btn {
  display: block;
  text-align: center;
  padding: 0.4rem;
  margin: 0.5rem;
  background: rgba(26, 26, 46, 0.5);
  border: 1px dashed #444;
  border-radius: 4px;
  cursor: pointer;
  font-size: 0.85rem;
  color: #aaa;
  touch-action: auto;
}
.upload-btn:hover { border-color: #4a4aff; color: #ccc; }

/* ── Status bar ── */
#status-bar {
  bottom: 68px;
  left: 8px;
  padding: 0.25rem 0.5rem;
  font-size: 0.75rem;
  color: #aaa;
  pointer-events: none;
  min-width: 0;
}
#status-bar:empty { display: none; }

/* ── Player badge: top-left corner pill ── */
#player-badge {
  top: 8px;
  left: 8px;
  display: flex;
  align-items: center;
  padding: 0.3rem 0.75rem;
  height: 36px;
  border-radius: 18px;
}
#player-info {
  display: flex;
  align-items: center;
  gap: 0.4rem;
  font-size: 0.9rem;
}
.player-dot {
  display: inline-block;
  width: 12px;
  height: 12px;
  border-radius: 50%;
  border: 1px solid rgba(255, 255, 255, 0.3);
  flex-shrink: 0;
}

/* ── Toast ── */
.toast {
  position: fixed;
  bottom: 1rem;
  left: 50%;
  transform: translateX(-50%);
  background: rgba(26, 26, 46, 0.95);
  border: 1px solid #2a2a4a;
  border-radius: 4px;
  padding: 0.4rem 0.8rem;
  font-size: 0.85rem;
  color: #ccc;
  pointer-events: none;
  z-index: 100;
}

/* ── Removal overlay ── */
.removal-overlay {
  position: fixed;
  inset: 0;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 1rem;
  background: rgba(13, 13, 26, 0.92);
  backdrop-filter: blur(8px);
  -webkit-backdrop-filter: blur(8px);
  z-index: 200;
}
.removal-overlay p {
  font-size: 1.1rem;
  color: #ccc;
}
.removal-overlay a {
  color: #4a4aff;
  text-decoration: none;
}
.removal-overlay a:hover { text-decoration: underline; }

